const text = String($json.text ?? '')
  .trim()
  .toLowerCase();

const timezone = 'Asia/Barnaul';

// Сегодняшняя календарная дата в timezone бизнеса
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date());

const getPart = (type) =>
  Number(parts.find(p => p.type === type).value);

const today = new Date(Date.UTC(
  getPart('year'),
  getPart('month') - 1,
  getPart('day')
));

const pad = (n) => String(n).padStart(2, '0');

const formatDate = (date) =>
  `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`;

const addDays = (date, days) => {
  const result = new Date(date);
  result.setUTCDate(result.getUTCDate() + days);
  return result;
};

// JS \b некорректно работает с кириллицей
const hasWord = (word) =>
  new RegExp(
    `(^|[^\\p{L}\\p{N}_])${word}($|[^\\p{L}\\p{N}_])`,
    'u'
  ).test(text);

const makeDate = (year, month, day) => {
  const date = new Date(Date.UTC(year, month - 1, day));

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return date;
};

const result = {
  status: 'unclear',
  date: null,
  raw_text: text,
  timezone,
};

// Сегодня / завтра / послезавтра
if (hasWord('сегодня')) {
  result.status = 'parsed';
  result.date = formatDate(today);

} else if (hasWord('послезавтра')) {
  result.status = 'parsed';
  result.date = formatDate(addDays(today, 2));

} else if (hasWord('завтра')) {
  result.status = 'parsed';
  result.date = formatDate(addDays(today, 1));

} else {

  // Дни недели
  const weekdays = {
    'понедельник': 1,
    'понедельника': 1,
    'вторник': 2,
    'вторника': 2,
    'среду': 3,
    'среда': 3,
    'среды': 3,
    'четверг': 4,
    'четверга': 4,
    'пятницу': 5,
    'пятница': 5,
    'пятницы': 5,
    'субботу': 6,
    'суббота': 6,
    'субботы': 6,
    'воскресенье': 7,
    'воскресенья': 7,
  };

  let matchedWeekday = null;

  for (const [word, isoDay] of Object.entries(weekdays)) {
    if (text.includes(word)) {
      matchedWeekday = isoDay;
      break;
    }
  }

  if (matchedWeekday !== null) {
    const jsDay = today.getUTCDay();
    const currentIsoDay = jsDay === 0 ? 7 : jsDay;

    // "через 2 недели", "через две недели", "через неделю"
    const weekWords = {
      'один': 1,
      'одну': 1,
      'два': 2,
      'две': 2,
      'три': 3,
      'четыре': 4,
      'пять': 5,
      'шесть': 6,
      'семь': 7,
      'восемь': 8,
      'девять': 9,
      'десять': 10,
    };

    const relativeWeeksMatch = text.match(
      /через\s+(\d+|один|одну|два|две|три|четыре|пять|шесть|семь|восемь|девять|десять)?\s*недел(?:ю|и|ь)/u
    );

    let relativeWeeks = null;

    if (relativeWeeksMatch) {
      const rawWeeks = relativeWeeksMatch[1];

      if (!rawWeeks) {
        relativeWeeks = 1;
      } else if (/^\d+$/.test(rawWeeks)) {
        relativeWeeks = Number(rawWeeks);
      } else {
        relativeWeeks = weekWords[rawWeeks] ?? null;
      }
    }

    let delta;

    if (relativeWeeks !== null) {
      delta =
        (relativeWeeks * 7) +
        (matchedWeekday - currentIsoDay);

    } else if (text.includes('следующ')) {
      delta = matchedWeekday - currentIsoDay + 7;

    } else {
      delta = (matchedWeekday - currentIsoDay + 7) % 7;
    }

    result.status = 'parsed';
    result.date = formatDate(addDays(today, delta));

  } else {

    // Месяцы
    const months = {
      'январь': 1,
      'января': 1,
      'февраль': 2,
      'февраля': 2,
      'март': 3,
      'марта': 3,
      'апрель': 4,
      'апреля': 4,
      'май': 5,
      'мая': 5,
      'июнь': 6,
      'июня': 6,
      'июль': 7,
      'июля': 7,
      'август': 8,
      'августа': 8,
      'сентябрь': 9,
      'сентября': 9,
      'октябрь': 10,
      'октября': 10,
      'ноябрь': 11,
      'ноября': 11,
      'декабрь': 12,
      'декабря': 12,
    };

    const monthNames = Object.keys(months).join('|');

    // Порядковые числительные для дат словами
    const ordinalDays = {
      'первое': 1,
      'второе': 2,
      'третье': 3,
      'четвертое': 4,
      'четвёртое': 4,
      'пятое': 5,
      'шестое': 6,
      'седьмое': 7,
      'восьмое': 8,
      'девятое': 9,
      'десятое': 10,
      'одиннадцатое': 11,
      'двенадцатое': 12,
      'тринадцатое': 13,
      'четырнадцатое': 14,
      'пятнадцатое': 15,
      'шестнадцатое': 16,
      'семнадцатое': 17,
      'восемнадцатое': 18,
      'девятнадцатое': 19,
      'двадцатое': 20,
      'двадцать первое': 21,
      'двадцать второе': 22,
      'двадцать третье': 23,
      'двадцать четвертое': 24,
      'двадцать четвёртое': 24,
      'двадцать пятое': 25,
      'двадцать шестое': 26,
      'двадцать седьмое': 27,
      'двадцать восьмое': 28,
      'двадцать девятое': 29,
      'тридцатое': 30,
      'тридцать первое': 31,
    };

    const ordinalNames = Object.keys(ordinalDays)
      .sort((a, b) => b.length - a.length)
      .join('|');

    // 5 мая / 5 мая 2027
    const wordDate = text.match(
      new RegExp(`(\\d{1,2})\\s+(${monthNames})(?:\\s+(\\d{4}))?`, 'u')
    );

    // шестое октября / двадцать первое октября
    const ordinalDate = text.match(
      new RegExp(`(${ordinalNames})\\s+(${monthNames})(?:\\s+(\\d{4}))?`, 'u')
    );

    // 14.09 / 14.09.2026
    const numericDate = text.match(
      /\b(\d{1,2})[./-](\d{1,2})(?:[./-](\d{4}))?\b/
    );

    let day;
    let month;
    let year;
    let explicitYear = false;

    if (wordDate) {
      day = Number(wordDate[1]);
      month = months[wordDate[2]];
      explicitYear = Boolean(wordDate[3]);
      year = wordDate[3]
        ? Number(wordDate[3])
        : today.getUTCFullYear();

    } else if (ordinalDate) {
      day = ordinalDays[ordinalDate[1]];
      month = months[ordinalDate[2]];
      explicitYear = Boolean(ordinalDate[3]);
      year = ordinalDate[3]
        ? Number(ordinalDate[3])
        : today.getUTCFullYear();

    } else if (numericDate) {
      day = Number(numericDate[1]);
      month = Number(numericDate[2]);
      explicitYear = Boolean(numericDate[3]);
      year = numericDate[3]
        ? Number(numericDate[3])
        : today.getUTCFullYear();
    }

    if (day && month && year) {
      let parsed = makeDate(year, month, day);

      if (parsed) {
        if (!explicitYear && parsed < today) {
          parsed = makeDate(year + 1, month, day);
        }

        if (parsed < today) {
          result.status = 'past';
          result.date = formatDate(parsed);
        } else {
          result.status = 'parsed';
          result.date = formatDate(parsed);
        }
      }
    }
  }
}

return [{ json: result }];

const data = $input.first().json;
const slots = data.slots ?? [];

const leadId = $('Save Appointment Date').first().json.id;

const rows = [];

for (let i = 0; i < slots.length; i += 3) {
  const row = slots.slice(i, i + 3).map(slot => {
    const unixStart = Math.floor(
      new Date(slot.starts_at).getTime() / 1000
    );

    return {
      text: slot.local_start_time,
      callback_data: `slot|${leadId}|${unixStart}`,
    };
  });

  rows.push(row);
}

return [
  {
    json: {
      lead_id: leadId,
      requested_appointment_date: data.requested_appointment_date,
      local_date: slots[0]?.local_date ?? null,
      timezone: slots[0]?.timezone ?? null,
      slot_count: slots.length,
      inline_keyboard: rows,
    },
  },
];

